let colors = ["#3ec1d3", "#f6f7d7", "#f6f7d7", "#ff165d"];
let mySeed;

function setup() {
  createCanvas(1000, 1000);
  rectMode(CENTER);
  ellipseMode(CENTER);
  strokeCap(SQUARE);
  colorMode(HSB, 360, 100, 100, 100);
  mySeed = floor(random(1, 100000));
}

function draw() {
  randomSeed(mySeed);

 fill(0);
 square(width/2,height/2,width);

  let mySize = 100;

  for (let xx = mySize; xx <= width - mySize; xx += mySize) {
    for (let yy = mySize; yy <= height - mySize; yy += mySize) {

      let xPos  = xx;
      let yPos  = yy;
      let amp   = mySize / 4;
      let ang   = random([0, PI/2, PI, 3*PI/2]);
      let step  = random(1, 6);
      let len   = mySize*0.75;
      let thick = 2;
      let freq  = random(1,3);

      drawSquareWave(xPos, yPos, freq, amp, ang, step, len, thick);
		drawWave(xPos, yPos, freq, amp, ang, step, len, thick);

    }
  }
}

function drawWave(xpos, ypos, freq, amp, ang, step, len, thick) {
  push();
  translate(xpos, ypos);
  rotate(ang);
  const strokeCol = generateColor();
  const fillCol   = generateColor();
  strokeWeight(thick);
  stroke(strokeCol);
  fill(fillCol);
	noFill();
  const phase = 0.025*frameCount;

  beginShape();
  for (let xx = -len / 2; xx <= len / 2; xx += step) {
    amp -= 1;
    const yy = amp * cos(xx*freq + phase);
    curveVertex(xx, yy);
  }

  endShape();
  pop();
}
function drawSquareWave(xpos, ypos, freq, amp, ang, step, len, thick) {
  push();
  translate(xpos, ypos);
  rotate(ang);

  const strokeCol = generateColor();
  const fillCol   = generateColor();
  strokeWeight(thick);
  stroke(strokeCol);
  noFill();  

  const phase = 0.025 * frameCount;

  beginShape();
  let prevY = null;

  for (let xx = -len / 2; xx <= len / 2; xx += step) {
    const s  = cos(xx * freq + phase);
    const yy = (s >= 0) ? amp : -amp;

    if (prevY === null) {
      vertex(xx, yy);
    } else {
      if (yy !== prevY) {
        vertex(xx, prevY);
        vertex(xx, yy);
      } else {
        vertex(xx, yy);
      }
    }
    prevY = yy;
  }

  endShape();
  pop();
}


function generateColor() {
  let myColor = color(random(colors));
  myColor.setAlpha(random(50, 100));
  return myColor;
}


